import io
import unittest

class Penghitung:
    def __init__(self):
        self.nilai = 0

    def tambah(self, jumlah):
        if type(jumlah) is not int or jumlah <= 0:
            raise ValueError("Jumlah harus integer positif")
        self.nilai += jumlah

class TesPenghitung(unittest.TestCase):
    def test_normal_dan_terpisah(self):
        a, b = Penghitung(), Penghitung()
        a.tambah(2)
        self.assertEqual(a.nilai, 2)
        self.assertEqual(b.nilai, 0)

    def test_invalid_tidak_mengubah(self):
        a = Penghitung()
        a.tambah(3)
        for nilai in (0, -1, True, 1.5):
            with self.assertRaises(ValueError):
                a.tambah(nilai)
            self.assertEqual(a.nilai, 3)

suite = unittest.defaultTestLoader.loadTestsFromTestCase(TesPenghitung)
hasil = unittest.TextTestRunner(stream=io.StringIO()).run(suite)
print("Tes dijalankan:", hasil.testsRun)
print("Semua lolos:", hasil.wasSuccessful())

def integer(nilai, minimum):
    if type(nilai) is not int or nilai < minimum:
        raise ValueError(f"Nilai harus integer >= {minimum}")
    return nilai

class Barang:
    def __init__(self, kode, harga, stok=0):
        if not isinstance(kode, str) or not kode.strip():
            raise ValueError("Kode wajib diisi")
        self._kode = kode.strip()
        self._harga = integer(harga, 0)
        self._stok = integer(stok, 0)

    @property
    def kode(self):
        return self._kode

    @property
    def harga(self):
        return self._harga

    @property
    def stok(self):
        return self._stok

    def tambah(self, jumlah):
        self._stok += integer(jumlah, 1)

    def keluarkan(self, jumlah):
        jumlah = integer(jumlah, 1)
        if jumlah > self._stok:
            raise ValueError("Stok tidak cukup")
        self._stok -= jumlah

    def nilai_persediaan(self):
        return self.harga * self.stok

