import math

def angka(nilai):
    if type(nilai) not in (int, float) or not math.isfinite(nilai):
        raise ValueError("Suhu harus angka terbatas")
    return nilai

class PembacaSimulasi:
    def __init__(self, data):
        self._data = iter(list(data))

    def baca(self):
        return next(self._data)

class Monitor:
    def __init__(self, pembaca, batas=35):
        self.pembaca = pembaca
        self.batas = angka(batas)

    def periksa(self):
        nilai = angka(self.pembaca.baca())
        status = "WASPADA" if nilai >= self.batas else "NORMAL"
        return nilai, status

