import json
from pathlib import Path
from tempfile import TemporaryDirectory

class Barang:
    def __init__(self, kode, stok):
        if not isinstance(kode, str) or not kode.strip():
            raise ValueError("Kode wajib diisi")
        if type(stok) is not int or stok < 0:
            raise ValueError("Stok harus integer >= 0")
        self._kode = kode.strip()
        self._stok = stok

    @property
    def kode(self):
        return self._kode

    @property
    def stok(self):
        return self._stok

    def to_dict(self):
        return {"kode": self.kode, "stok": self.stok}

    @classmethod
    def from_dict(cls, data):
        if not isinstance(data, dict) or set(data) != {"kode", "stok"}:
            raise ValueError("Field barang tidak sesuai")
        return cls(data["kode"], data["stok"])

def simpan(path, barang):
    data = Barang.from_dict(barang.to_dict()).to_dict()
    teks = json.dumps({"versi": 1, "barang": data}, ensure_ascii=False, indent=2)
    Path(path).write_text(teks, encoding="utf-8")

def muat(path):
    data = json.loads(Path(path).read_text(encoding="utf-8"))
    if not isinstance(data, dict) or set(data) != {"versi", "barang"}:
        raise ValueError("Format file tidak sesuai")
    if type(data["versi"]) is not int or data["versi"] != 1:
        raise ValueError("Versi belum didukung")
    return Barang.from_dict(data["barang"])

with TemporaryDirectory() as folder:
    path = Path(folder) / "barang_latihan.json"
    asli = Barang(" K01 ", 3)
