class Kanal:
    def __init__(self):
        self._penerima = []

    def daftar(self, callback):
        if not callable(callback):
            raise ValueError("Penerima harus callable")
        if callback not in self._penerima:
            self._penerima.append(callback)

    def lepas(self, callback):
        if callback in self._penerima:
            self._penerima.remove(callback)

