import json
from pathlib import Path
from tempfile import TemporaryDirectory

def teks(nilai):
    if not isinstance(nilai, str) or not nilai.strip():
        raise ValueError("Teks wajib diisi")
    return nilai.strip()

def bentuk(data, field):
    if not isinstance(data, dict) or set(data) != set(field):
        raise ValueError("Field data tidak sesuai")

class Teknisi:
    def __init__(self, kode, nama):
        self.kode, self.nama = teks(kode), teks(nama)

class Tiket:
    def __init__(self, nomor, judul):
        self.nomor, self.judul = teks(nomor), teks(judul)
        self._teknisi = None
        self._riwayat = ["BARU"]

    @property
    def status(self):
        return self._riwayat[-1]

    @property
    def riwayat(self):
        return tuple(self._riwayat)

    @property
    def teknisi(self):
        return self._teknisi

    def _ubah(self, awal, tujuan):
        if self.status != awal:
            raise ValueError("Perpindahan status tidak diizinkan")
        self._riwayat.append(tujuan)

    def tugaskan(self, kode):
        kode = teks(kode)
        if self.status != "BARU":
            raise ValueError("Hanya tiket BARU dapat ditugaskan")
        self._teknisi = kode
        self._ubah("BARU", "DITUGASKAN")

    def proses(self):
        self._ubah("DITUGASKAN", "DIPROSES")

    def selesaikan(self):
        self._ubah("DIPROSES", "SELESAI")

class LayananTiket:
    def __init__(self):
        self._teknisi, self._tiket = {}, {}

    def tambah_teknisi(self, kode, nama):
        orang = Teknisi(kode, nama)
        if orang.kode in self._teknisi:
            raise ValueError("Kode teknisi duplikat")
        self._teknisi[orang.kode] = orang

    def buat(self, nomor, judul):
        tiket = Tiket(nomor, judul)
        if tiket.nomor in self._tiket:
            raise ValueError("Nomor tiket duplikat")
        self._tiket[tiket.nomor] = tiket

    def ambil(self, nomor):
        nomor = teks(nomor)
        if nomor not in self._tiket:
            raise ValueError("Tiket tidak ditemukan")
        return self._tiket[nomor]

    def tugaskan(self, nomor, kode):
        kode = teks(kode)
        if kode not in self._teknisi:
            raise ValueError("Teknisi tidak ditemukan")
        self.ambil(nomor).tugaskan(kode)

    def proses(self, nomor):
        self.ambil(nomor).proses()

    def selesaikan(self, nomor):
        self.ambil(nomor).selesaikan()

    def to_dict(self):
        return {"versi": 1,
                "teknisi": [{"kode": t.kode, "nama": t.nama} for t in self._teknisi.values()],
                "tiket": [{"nomor": t.nomor, "judul": t.judul, "teknisi": t.teknisi,
                           "riwayat": list(t.riwayat)} for t in self._tiket.values()]}

    @classmethod
    def from_dict(cls, data):
        bentuk(data, ("versi", "teknisi", "tiket"))
        if type(data["versi"]) is not int or data["versi"] != 1:
            raise ValueError("Versi tidak didukung")
        if not isinstance(data["teknisi"], list) or not isinstance(data["tiket"], list):
            raise ValueError("Koleksi harus list")
        hasil = cls()
        for orang in data["teknisi"]:
            bentuk(orang, ("kode", "nama"))
            hasil.tambah_teknisi(orang["kode"], orang["nama"])
        alur = ["BARU", "DITUGASKAN", "DIPROSES", "SELESAI"]
        for item in data["tiket"]:
            bentuk(item, ("nomor", "judul", "teknisi", "riwayat"))
            riwayat = item["riwayat"]
            if not isinstance(riwayat, list) or not 1 <= len(riwayat) <= 4:
                raise ValueError("Riwayat tidak valid")
            if riwayat != alur[:len(riwayat)]:
                raise ValueError("Urutan riwayat tidak valid")
            if len(riwayat) == 1 and item["teknisi"] is not None:
                raise ValueError("Tiket BARU belum mempunyai teknisi")
            hasil.buat(item["nomor"], item["judul"])
            nomor = item["nomor"]
            if len(riwayat) >= 2:
                hasil.tugaskan(nomor, item["teknisi"])
            if len(riwayat) >= 3:
                hasil.proses(nomor)
            if len(riwayat) == 4:
                hasil.selesaikan(nomor)
        return hasil

def simpan(path, layanan):
    data = LayananTiket.from_dict(layanan.to_dict()).to_dict()
    Path(path).write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")

def muat(path):
    data = json.loads(Path(path).read_text(encoding="utf-8"))
    return LayananTiket.from_dict(data)

def main():
    layanan = LayananTiket()
    layanan.tambah_teknisi("N01", "Ana")
    layanan.buat("T01", "Link pelanggan putus")
    try:
        layanan.selesaikan("T01")
    except ValueError as error:
        print("Ditolak:", error)
    layanan.tugaskan("T01", "N01")
    layanan.proses("T01")
    layanan.selesaikan("T01")
    with TemporaryDirectory() as folder:
        path = Path(folder) / "tiket.json"
        simpan(path, layanan)
        pulih = muat(path)
        tiket = pulih.ambil("T01")
        print(tiket.nomor, tiket.teknisi, tiket.status)
        print(" -> ".join(tiket.riwayat))
        print("Data sama:", pulih.to_dict() == layanan.to_dict())

if __name__ == "__main__":
    main()
